/**
 * generated by stackra gen from the consumed manifests' settings sections (commerce: orders,
 * inventory; notifications: messages) — do not edit
 * Purpose: the typed setting keys (`Settings.orders.autoCancelAfterMinutes`,
 *          `Settings.messages.orderUpdates`) with their metadata,
 *          `Settings.pick`, which turns a list of keys into the Zod object with the declared bounds
 *          and defaults, and the generated settings pages per module.
 * Boundary: data; values are read and written through the settings actions at runtime; nothing here
 *           is a value. `messages` is user-scoped: its page edits the signed-in user's own
 *           notification preferences.
 * Runtime: browser
 */
import { SettingScope, SettingType, settingKeys, settingsPage } from "@stackra/settings";
import { I18n } from "#stackra/i18n";
import { Panels } from "#stackra/panels";

/** `<module>.<field>` → type, default, bounds, scopes, label; the same shape in every app. */
export const Settings = settingKeys({
  orders: {
    autoCancelAfterMinutes: {
      type: SettingType.Integer,
      default: 30,
      min: 5,
      max: 1440,
      scopes: [SettingScope.Platform, SettingScope.Tenant],
      renamedFrom: ["autoCancelMinutes"],
      label: I18n.orders.settings.auto_cancel_after_minutes,
    },
    customersMayCancel: {
      type: SettingType.Boolean,
      default: true,
      lockable: true,
      scopes: [SettingScope.Platform, SettingScope.Tenant],
      label: I18n.orders.settings.customers_may_cancel,
    },
  },
  inventory: {
    lowStockThreshold: {
      type: SettingType.Integer,
      default: 5,
      min: 0,
      scopes: [SettingScope.Platform, SettingScope.Tenant],
      label: I18n.inventory.settings.low_stock_threshold,
    },
    allowBackorders: {
      type: SettingType.Boolean,
      default: false,
      scopes: [SettingScope.Platform, SettingScope.Tenant],
      label: I18n.inventory.settings.allow_backorders,
    },
  },
  messages: {
    orderUpdates: {
      type: SettingType.Boolean,
      default: true,
      scopes: [SettingScope.User],
      label: I18n.messages.settings.order_updates,
    },
    orderReceipts: {
      type: SettingType.Boolean,
      default: true,
      scopes: [SettingScope.User],
      label: I18n.messages.settings.order_receipts,
    },
    productUpdates: {
      type: SettingType.Boolean,
      default: false,
      scopes: [SettingScope.User],
      label: I18n.messages.settings.product_updates,
    },
    marketing: {
      type: SettingType.Boolean,
      default: false,
      scopes: [SettingScope.User],
      label: I18n.messages.settings.marketing,
    },
  },
});

/**
 * One generated page per module, each gated by its `<module>.settings.update` permission or,
 * user-scoped, by none.
 */
export const SettingsPages = {
  orders: settingsPage("orders", { panels: [Panels.TenantAdmin], scope: SettingScope.Tenant }),
  inventory: settingsPage("inventory", {
    panels: [Panels.TenantAdmin],
    scope: SettingScope.Tenant,
  }),
  messages: settingsPage("messages", { panels: [Panels.TenantAdmin], scope: SettingScope.User }),
} as const;
